// android/ and ios/ are not in git: they are generated by `expo prebuild`
// (see README / INFO.md). The few things that used to be edited by hand in
// those folders live here instead, so every prebuild puts them back.
const fs = require("fs");
const path = require("path");
const {
  AndroidConfig,
  withAndroidManifest,
  withAppDelegate,
  withDangerousMod,
  withGradleProperties,
} = require("expo/config-plugins");

const POD_TARGET_MARKER = "# [withNativeTweaks] clamp pod deployment targets";
const POD_ARCH_MARKER = "# [withNativeTweaks] ensure new arch env for podspecs";

// react_native_post_install only raises a pod's deployment target up to the
// app's minimum (15.1) - it never lowers one. A pod whose podspec asks for
// more (e.g. 16.0) keeps compiling against it, which can weak-link APIs
// wrongly and crash through dyld at launch on iOS 15. Forcing every pod down
// to the app's own target turns that into a build-time availability error.
const POD_TARGET_BLOCK = `
    ${POD_TARGET_MARKER}
    app_deployment_target = podfile_properties['ios.deploymentTarget'] || '15.1'
    installer.pods_project.targets.each do |target|
      target.build_configurations.each do |build_config|
        build_config.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = app_deployment_target
      end
    end
`;

const withPodfileTweaks = (config) =>
  withDangerousMod(config, [
    "ios",
    (cfg) => {
      const podfile = path.join(cfg.modRequest.platformProjectRoot, "Podfile");
      if (!fs.existsSync(podfile)) return cfg;

      let contents = fs.readFileSync(podfile, "utf8");

      // Set RCT_NEW_ARCH_ENABLED at the top so any podspecs requiring it
      // during use_native_modules! will find it set.
      if (!contents.includes(POD_ARCH_MARKER)) {
        contents = contents.replace(
          /(platform :ios[^\n]*\n)/,
          `$1${POD_ARCH_MARKER}\nENV['RCT_NEW_ARCH_ENABLED'] ||= '1'\n`
        );
      }

      if (!contents.includes(POD_TARGET_MARKER)) {
        // Right after the react_native_post_install(...) call, inside post_install.
        const next = contents.replace(
          /(react_native_post_install\([\s\S]*?\n\s*\)\n)/,
          `$1${POD_TARGET_BLOCK}`
        );
        if (next === contents) {
          console.warn("[withNativeTweaks] react_native_post_install not found in Podfile; deployment targets not clamped");
        } else {
          contents = next;
        }
      }

      fs.writeFileSync(podfile, contents);
      return cfg;
    },
  ]);

// Large screens (tablets, foldables, split screen): Google Play's large
// screen quality rules want the activity resizeable even though the app
// itself stays portrait.
const withResizeableActivity = (config) =>
  withAndroidManifest(config, (cfg) => {
    const activity = AndroidConfig.Manifest.getMainActivityOrThrow(cfg.modResults);
    activity.$["android:resizeableActivity"] = "true";
    return cfg;
  });

// CI signs the APK with this keystore. It is kept outside android/ so every
// build - whichever machine prebuilt the project - has the same signature;
// with a different one, Android refuses to install the APK over an existing
// install.
// Incoming calls (Zalo / Messenger style lockscreen popup): allow MainActivity
// to wake the screen and display over the lockscreen when a full-screen intent
// or call push arrives.
const withIncomingCallLockscreenFlags = (config) =>
  withAndroidManifest(config, (cfg) => {
    const activity = AndroidConfig.Manifest.getMainActivityOrThrow(cfg.modResults);
    activity.$["android:showWhenLocked"] = "true";
    activity.$["android:turnScreenOn"] = "true";
    activity.$["android:showOnLockScreen"] = "true";
    activity.$["android:inheritShowWhenLocked"] = "true";

    AndroidConfig.Permissions.addPermission(cfg.modResults, "android.permission.USE_FULL_SCREEN_INTENT");
    AndroidConfig.Permissions.addPermission(cfg.modResults, "android.permission.WAKE_LOCK");
    AndroidConfig.Permissions.addPermission(cfg.modResults, "android.permission.VIBRATE");
    AndroidConfig.Permissions.addPermission(cfg.modResults, "android.permission.FOREGROUND_SERVICE");
    AndroidConfig.Permissions.addPermission(cfg.modResults, "android.permission.RECORD_AUDIO");
    AndroidConfig.Permissions.addPermission(cfg.modResults, "android.permission.MODIFY_AUDIO_SETTINGS");
    AndroidConfig.Permissions.addPermission(cfg.modResults, "android.permission.CAMERA");

    return cfg;
  });

const withStableDebugKeystore = (config) =>
  withDangerousMod(config, [
    "android",
    (cfg) => {
      const source = path.join(cfg.modRequest.projectRoot, "keystores", "debug.keystore");
      const target = path.join(cfg.modRequest.platformProjectRoot, "app", "debug.keystore");
      if (fs.existsSync(source) && fs.existsSync(path.dirname(target))) {
        fs.copyFileSync(source, target);
      }
      return cfg;
    },
  ]);

// Google Play Store builds (.aab) split strings and optimize/shrink resources, which
// can cause '@string/expo_runtime_version' to fail resolving or return an unparsed resource ID
// when expo-updates queries metadata, disabling OTA (Updates.isEnabled = false).
// Writing the literal runtimeVersion and update URL directly into AndroidManifest.xml
// guarantees expo-updates always validates successfully on Google Play installs.
const withDirectUpdatesMetadata = (config) =>
  withAndroidManifest(config, (cfg) => {
    const mainApp = AndroidConfig.Manifest.getMainApplicationOrThrow(cfg.modResults);
    const runtimeVersion = cfg.runtimeVersion || "7.4.10";
    const updateUrl = cfg.updates?.url || "https://api.chuyenbienhoa.com/v1.0/ota/manifest";
    const requestHeadersJson = JSON.stringify(
      cfg.updates?.requestHeaders || { "expo-channel-name": "production" }
    );

    AndroidConfig.Manifest.addMetaDataItemToMainApplication(
      mainApp,
      "expo.modules.updates.EXPO_RUNTIME_VERSION",
      String(runtimeVersion)
    );
    AndroidConfig.Manifest.addMetaDataItemToMainApplication(
      mainApp,
      "expo.modules.updates.EXPO_UPDATE_URL",
      String(updateUrl)
    );
    AndroidConfig.Manifest.addMetaDataItemToMainApplication(
      mainApp,
      "expo.modules.updates.UPDATES_CONFIGURATION_REQUEST_HEADERS_KEY",
      requestHeadersJson
    );
    AndroidConfig.Manifest.addMetaDataItemToMainApplication(
      mainApp,
      "expo.modules.updates.ENABLED",
      "true"
    );
    return cfg;
  });

const IMAGE_CLASSES_MARKER = "[withNativeTweaks] image module classes";
const R8_PROGUARD_MARKER = "# [withNativeTweaks] R8 full-mode & native module ProGuard rules";

const R8_PROGUARD_RULES = `
${R8_PROGUARD_MARKER}
-optimizationpasses 5
-allowaccessmodification
-repackageclasses 'com.fatties.youth.obf'
-keepattributes SourceFile,LineNumberTable,*Annotation*,Signature,InnerClasses,EnclosingMethod

# React Native JSI / TurboModules / Fabric / Hermes
-keep,allowobfuscation @interface com.facebook.proguard.annotations.DoNotStrip
-keep,allowobfuscation @interface com.facebook.proguard.annotations.KeepGettersAndSetters
-keep,allowobfuscation @interface com.facebook.common.internal.DoNotStrip
-keep,allowobfuscation @interface com.facebook.jni.annotations.DoNotStrip
-keep @com.facebook.proguard.annotations.DoNotStrip class *
-keep @com.facebook.common.internal.DoNotStrip class *
-keep @com.facebook.jni.annotations.DoNotStrip class *
-keepclassmembers class * {
    @com.facebook.proguard.annotations.DoNotStrip *;
    @com.facebook.common.internal.DoNotStrip *;
    @com.facebook.jni.annotations.DoNotStrip *;
}
-keepclassmembers @com.facebook.proguard.annotations.KeepGettersAndSetters class * {
    void set*(***);
    *** get*();
}
-keep class * extends com.facebook.jni.HybridData { *; }
-keep class com.facebook.jni.** { *; }
-keep class com.facebook.hermes.** { *; }
-keep class com.facebook.react.bridge.** { *; }
-keep class com.facebook.react.turbomodule.** { *; }
-keep class com.facebook.react.uimanager.** { *; }
-keep class * implements com.facebook.react.bridge.JavaScriptModule { *; }
-keep class * implements com.facebook.react.bridge.NativeModule { *; }
-keep class * extends com.facebook.react.bridge.ReactContextBaseJavaModule { *; }
-keep class * implements com.facebook.react.turbomodule.core.interfaces.TurboModule { *; }

# Expo Modules Core
-keep class expo.modules.** { *; }
-keepclassmembers class * {
    @expo.modules.core.interfaces.ExpoMethod *;
}

# Reanimated / Worklets / GestureHandler / Screens
-keep class com.swmansion.reanimated.** { *; }
-keep class com.swmansion.worklets.** { *; }
-keep class com.swmansion.gesturehandler.** { *; }
-keep class com.swmansion.rnscreens.** { *; }

# Skia / Liquid Glassmorphism
-keep class com.shopify.reactnative.skia.** { *; }

# WebRTC & InCallManager
-keep class com.oney.WebRTCModule.** { *; }
-keep class org.webrtc.** { *; }
-keep class com.zxcpoiu.incallmanager.** { *; }

# FastImage & Glide
-keep class com.dylanvann.fastimage.** { *; }
-keep public class * implements com.bumptech.glide.module.GlideModule
-keep class * extends com.bumptech.glide.module.AppGlideModule {
    <init>(...);
}

# VisionCamera & Compressor
-keep class com.mrousavy.camera.** { *; }
-keep class com.reactnativecompressor.** { *; }

# MMKV & NitroModules
-keep class com.margelo.nitro.** { *; }
-keep class com.tencent.mmkv.** { *; }

# Notifee & Firebase Messaging
-keep class app.notifee.core.** { *; }
-keep class io.invertase.notifee.** { *; }
-dontwarn app.notifee.**

# Passkeys & AndroidX Credentials
-keep class com.reactnativepasskey.** { *; }
-keep class androidx.credentials.** { *; }
-dontwarn androidx.credentials.**

# OkHttp / Okio / Retrofit / Gson reflection safety under R8 fullMode
-dontwarn okhttp3.**
-dontwarn okio.**
-dontwarn javax.annotation.**
-dontwarn org.conscrypt.**
-dontwarn org.bouncycastle.**
-dontwarn org.openjsse.**
-keepattributes Signature, InnerClasses, EnclosingMethod
-keepclassmembers,allowshrinking,allowobfuscation interface * {
    @retrofit2.http.* <methods>;
}
`;

const setGradleProp = (props, key, value) => {
  const existing = props.find((item) => item.type === "property" && item.key === key);
  if (existing) {
    existing.value = value;
  } else {
    props.push({ type: "property", key, value });
  }
};

// Enable Google's strict R8 full mode, code shrinking, and resource shrinking
// in Android release builds while keeping JNI / JSI / TurboModule entrypoints safe.
const withAndroidR8FullMode = (config) =>
  withGradleProperties(config, (cfg) => {
    const props = cfg.modResults;
    setGradleProp(props, "android.enableR8.fullMode", "true");
    setGradleProp(props, "android.enableProguardInReleaseBuilds", "true");
    setGradleProp(props, "android.enableShrinkResourcesInReleaseBuilds", "true");
    return cfg;
  });

const withAndroidProguardRules = (config) =>
  withDangerousMod(config, [
    "android",
    (cfg) => {
      const proguardFile = path.join(
        cfg.modRequest.platformProjectRoot,
        "app",
        "proguard-rules.pro"
      );
      if (!fs.existsSync(proguardFile)) return cfg;

      const contents = fs.readFileSync(proguardFile, "utf8");
      if (!contents.includes(R8_PROGUARD_MARKER)) {
        fs.writeFileSync(proguardFile, `${contents.trimEnd()}\n${R8_PROGUARD_RULES}`);
      }
      return cfg;
    },
  ]);

// React Native's image modules ("ImageLoader", ...) are not in the class table
// open-source builds use, so the TurboModule manager finds them by name:
// NSClassFromString("ImageLoader") first, "RCTImageLoader" only if that is nil.
// On iOS 15 the first lookup returns some other class called ImageLoader, the
// module is then reported as "could not be found", and the app failed at
// launch (React Native's Image needs it; iOS 16+ was fine). Naming the classes
// in the app's delegate skips that lookup. A plain @objc method, not an
// override: Swift does not see RCTTurboModuleManagerDelegate (C++ only), but
// React Native calls the selector at runtime.
const IMAGE_CLASSES_METHOD = `
  // ${IMAGE_CLASSES_MARKER}
  @objc(getModuleClassFromName:)
  func getModuleClassFromName(_ name: UnsafePointer<CChar>) -> AnyClass? {
    switch String(cString: name) {
    case "ImageLoader": return NSClassFromString("RCTImageLoader")
    case "ImageStoreManager": return NSClassFromString("RCTImageStoreManager")
    case "ImageEditingManager": return NSClassFromString("RCTImageEditingManager")
    case "LocalAssetImageLoader": return NSClassFromString("RCTLocalAssetImageLoader")
    case "GIFImageDecoder": return NSClassFromString("RCTGIFImageDecoder")
    default: return nil
    }
  }
`;

const withImageModuleClasses = (config) =>
  withAppDelegate(config, (cfg) => {
    const delegate = cfg.modResults;
    if (delegate.language !== "swift" || delegate.contents.includes(IMAGE_CLASSES_MARKER)) return cfg;

    const next = delegate.contents.replace(
      /(class ReactNativeDelegate: ExpoReactNativeFactoryDelegate \{\n)/,
      `$1${IMAGE_CLASSES_METHOD}`
    );
    if (next === delegate.contents) {
      console.warn("[withNativeTweaks] ReactNativeDelegate not found in AppDelegate.swift; image module classes not added");
      return cfg;
    }
    delegate.contents = next;
    return cfg;
  });

module.exports = (config) =>
  withAndroidProguardRules(
    withAndroidR8FullMode(
      withDirectUpdatesMetadata(
        withImageModuleClasses(
          withIncomingCallLockscreenFlags(
            withStableDebugKeystore(withResizeableActivity(withPodfileTweaks(config)))
          )
        )
      )
    )
  );
